/// Macro used to temporarily "open" a [`LocalInvariant`] object, obtaining the stored
/// value within.
///
/// ### Usage
///
/// The form of the macro looks like,
///
/// ```rust

    pred: Pred,
}

impl<V, Pred: RwLockPredicate<V>> InvariantPredicate<
    (Pred, CellId),
    un::PointsTo<V>,
> for InternalPred<V, Pred> {
    closed spec fn inv(k: (Pred, CellId), v: un::PointsTo<V>) -> bool {
        v.id() == k.1 && v.is_init() && k.0.inv(v.value())
    }
}

struct_with_invariants!{
    /** A verified implementation of a reader-writer lock,
    implemented using atomics and a reference count.

    When constructed, you can provide an invariant via the `Pred` parameter,
    specifying the allowed values that can go in the lock.

    Note that this specification does *not* verify the absence of dead-locks.

    ### Examples

    On construction of a lock, we can specify an invariant for the object that goes inside.
    One way to do this is by providing a `spec_fn`, which implements the [`RwLockPredicate`]
    trait.

    ```rust,ignore
    fn example1() {
        // We can create a lock with an invariant: `v == 5 || v == 13`.
        // Thus only 5 or 13 can be stored in the lock.
        let lock = RwLock::<u64, spec_fn(u64) -> bool>::new(5, Ghost(|v| v == 5 || v == 13));

        let (val, write_handle) = lock.acquire_write();
        assert(val == 5 || val == 13);
        write_handle.release_write(13);

        let read_handle1 = lock.acquire_read();
        let read_handle2 = lock.acquire_read();

        // We can take multiple read handles at the same time:

        let val1 = read_handle1.borrow();
        let val2 = read_handle2.borrow();

        // RwLock has a lemma that both read handles have the same value:

        proof { ReadHandle::lemma_readers_match(&read_handle1, &read_handle2); }
        assert(*val1 == *val2);

        read_handle1.release_read();
        read_handle2.release_read();
    }
    ```

    It's often easier to implement the [`RwLockPredicate`] trait yourself. This way you can
    have a configurable predicate without needing to work with higher-order functions.

    ```rust,ignore
    struct FixedParity {
        pub parity: int,
    }

    impl RwLockPredicate<u64> for FixedParity {
        open spec fn inv(self, v: u64) -> bool {
            v % 2 == self.parity
        }
    }

    fn example2() {
        // Create a lock that can only store even integers
        let lock_even = RwLock::<u64, FixedParity>::new(20, Ghost(FixedParity { parity: 0 }));

        // Create a lock that can only store odd integers
        let lock_odd = RwLock::<u64, FixedParity>::new(23, Ghost(FixedParity { parity: 1 }));

        let read_handle_even = lock_even.acquire_read();
        let val_even = *read_handle_even.borrow();
        assert(val_even % 2 == 0);

        let read_handle_odd = lock_odd.acquire_read();
        let val_odd = *read_handle_odd.borrow();
        assert(val_odd % 2 == 1);
    }
    ```
    */

    pub struct RwLock<V, Pred: RwLockPredicate<V>> {
        cell: un::PCell<V>,
        exc: AtomicBool<_, RwLockToks::flag_exc<(Pred, CellId), un::PointsTo<V>, InternalPred<V, Pred>>, _>,
        rc: AtomicUsize<_, RwLockToks::flag_rc<(Pred, CellId), un::PointsTo<V>, InternalPred<V, Pred>>, _>,

        inst: Tracked<RwLockToks::Instance<(Pred, CellId), un::PointsTo<V>, InternalPred<V, Pred>>>,
        pred: Ghost<Pred>,
    }

    #[verifier::type_invariant]
    spec fn wf(&self) -> bool {
        invariant on exc with (inst) is (v: bool, g: RwLockToks::flag_exc<(Pred, CellId), un::PointsTo<V>, InternalPred<V, Pred>>) {
            g.instance_id() == inst@.id()
                && g.value() == v
        }

        invariant on rc with (inst) is (v: usize, g: RwLockToks::flag_rc<(Pred, CellId), un::PointsTo<V>, InternalPred<V, Pred>>) {
            g.instance_id() == inst@.id()
                && g.value() == v
        }

        predicate {
            self.inst@.k() == (self.pred@, self.cell.id())
        }
    }
}

/// Handle obtained for an exclusive write-lock from an [`RwLock`].
///
/// Note that this handle does not contain a reference to the lock-protected object;
/// ownership of the object is obtained separately from [`RwLock::acquire_write`].
/// This may be changed in the future.
///
/// **Warning:** The lock is _NOT_ released automatically when the handle
/// is dropped. You must call [`release_write`](WriteHandle::release_write).
/// Verus does not check that lock is released.
pub struct WriteHandle<'a, V, Pred: RwLockPredicate<V>> {
    handle: Tracked<RwLockToks::writer<(Pred, CellId), un::PointsTo<V>, InternalPred<V, Pred>>>,
    perm: Tracked<un::PointsTo<V>>,
    rwlock: &'a RwLock<V, Pred>,
}

/// Handle obtained for a shared read-lock from an [`RwLock`].
///
/// **Warning:** The lock is _NOT_ released automatically when the handle
/// is dropped. You must call [`release_read`](ReadHandle::release_read).
/// Verus does not check that lock is released.
pub struct ReadHandle<'a, V, Pred: RwLockPredicate<V>> {
    handle: Tracked<RwLockToks::reader<(Pred, CellId), un::PointsTo<V>, InternalPred<V, Pred>>>,
    rwlock: &'a RwLock<V, Pred>,
}

impl<'a, V, Pred: RwLockPredicate<V>> WriteHandle<'a, V, Pred> {
    #[verifier::type_invariant]
    spec fn wf_write_handle(self) -> bool {
        equal(self.perm@.id(), self.rwlock.cell.id()) && self.perm@.is_uninit() && equal(
            self.handle@.instance_id(),
            self.rwlock.inst@.id(),
        ) && self.rwlock.wf()
    }

    pub closed spec fn rwlock(self) -> RwLock<V, Pred> {
        *self.rwlock
    }

    pub fn release_write(self, new_val: V)
        requires
            self.rwlock().inv(new_val),
    {
        proof {
            use_type_invariant(&self);
        }
        let WriteHandle { handle: Tracked(handle), perm: Tracked(mut perm), rwlock } = self;
        self.rwlock.cell.put(Tracked(&mut perm), new_val);

        atomic_with_ghost!(
            &rwlock.exc => store(false);
            ghost g =>
        {
            self.rwlock.inst.borrow().release_exc(perm, &mut g, perm, handle);
        });
    }
}

impl<'a, V, Pred: RwLockPredicate<V>> ReadHandle<'a, V, Pred> {
    #[verifier::type_invariant]
    spec fn wf_read_handle(self) -> bool {
        equal(self.handle@.instance_id(), self.rwlock.inst@.id())
            && self.handle@.element().is_init() && equal(
            self.handle@.element().id(),
            self.rwlock.cell.id(),
        ) && self.rwlock.wf()
    }

#!/usr/bin/env python3

import os
import sys
import argparse
import re
import subprocess
from pathlib import Path
import tempfile
import logging

logger = logging.getLogger(__name__)

class LynetteCheckerError(RuntimeError):
    """The checker could not complete its analysis (for example, a parse error)."""


class Lynette:
    lynette_path = Path(__file__).resolve().parent/ "lynette" / "source"
    meta_command = ["cargo", "run", "--quiet", "--manifest-path", lynette_path / "Cargo.toml", "--"]
    env = os.environ.copy()
    env["RUSTFLAGS"] = "-Awarnings"

    # Run a command
    # @command: a list of lynette commands arguemnts, e.g. ["compare", "foo.rs", "bar.rs"]
    # @return: a CompletedProcess object(returned by subprocess.run(...))
    def run(self, command):
        command = self.meta_command + command
        return subprocess.run(command, env=self.env, capture_output=True, text=True)

    def code_unimpl(self, file):
        return self.run(["code", "unimpl", file])

    def func_add(self, file1, file2, replace=False, funcs=None):
        if funcs is None:
            funcs = []
        return self.run(
            ["func", "add", file1, file2, "--replace" if replace else ""] + ["--funcs"] + funcs
            if funcs
            else []
        )

    def code_merge(self, file1, file2, merge_mode):
        pass

    def code_merge_all(self, file1, file2):
        return self.run(["code", "merge", "--all", file1, file2])

    def code_merge_invariant(self, file1, file2):
        return self.run(["code", "merge", "--invariants", file1, file2])

    def code_detect_nonlinear(self, file):
        return self.run(["code", "detect-nl", file])

    def code_get_ghost(self, file):
        """Get all ghost code in a verus source code file.

        Returns a CompletedProcess with output format:
        <type>:((<start_line>, <start_column>), (<end_line>, <end_column>))
        """
        return self.run(["code", "get-ghost", file])

    def get_assertions(self, file):
        """Get assertion statements with their line numbers.

        Args:
            file: Path to the Verus source file

        Returns:
            List of dictionaries with assertion information:
            [
                {
                    'type': 'assert' or 'assert_forall',
                    'start_line': int,
                    'start_column': int,
                    'end_line': int,
                    'end_column': int
                },
                ...
            ]
        """
        result = self.code_get_ghost(file)
        if result.returncode != 0:
            return []

        assertions = []
        # Parse output lines like: assert:((32, 20), (32, 42))
        pattern = r"^(assert|assert_forall):\(\((\d+), (\d+)\), \((\d+), (\d+)\)\)$"

        for line in result.stdout.strip().split("\n"):
            if not line:
                continue
            match = re.match(pattern, line)
            if match:
                assertions.append(
                    {
                        "type": match.group(1),
                        "start_line": int(match.group(2)),
                        "start_column": int(match.group(3)),
                        "end_line": int(match.group(4)),
                        "end_column": int(match.group(5)),
                    }
                )

        return assertions

    def get_all_ghost_code(self, file):
        """Get all ghost code with their line numbers.

        Args:
            file: Path to the Verus source file

        Returns:
            List of dictionaries with ghost code information:
            [
                {
                    'type': str (e.g., 'assert', 'requires', 'ensures', etc.),
                    'start_line': int,
                    'start_column': int,
                    'end_line': int,
                    'end_column': int
                },
                ...
            ]
        """
        result = self.code_get_ghost(file)
        if result.returncode != 0:
            return []

        ghost_items = []
        # Parse output lines like: <type>:((<start_line>, <start_column>), (<end_line>, <end_column>))
        pattern = r"^([^:]+):\(\((\d+), (\d+)\), \((\d+), (\d+)\)\)$"

        for line in result.stdout.strip().split("\n"):
            if not line:
                continue
            match = re.match(pattern, line)
            if match:
                ghost_items.append(
                    {
                        "type": match.group(1),
                        "start_line": int(match.group(2)),
                        "start_column": int(match.group(3)),
                        "end_line": int(match.group(4)),
                        "end_column": int(match.group(5)),
                    }
                )

        return ghost_items


    def proof_completion_code_change_is_safe(
        self,
        origin: str,
        changed: str,
    ) -> bool:
        """
        Check if code changes are safe for proof completion.

        Ensures that no admit(), assume(), or verifier attributes are added/removed.
        Uses Lynette to verify changes don't violate safety rules.

        Args:
            origin: Original source code
            changed: Modified source code

        Returns:
            True if changes are safe, False otherwise
        """
        # Check the number of admit(), assume(, #[verifier::external_body]
        # They should not be increased
        if origin.count("admit()") != changed.count("admit()"):
            logger.error("admit() calls have been added or removed")
            return False
        if origin.count("assume(") != changed.count("assume("):
            logger.error("assume(...) calls have been added or removed")
            return False
        if origin.count("#[verifier::external_body]") != changed.count("#[verifier::external_body]"):
            logger.error("#[verifier::external_body] annotations have been added or removed")
            return False
        if origin.count("#[verifier::admit]") != changed.count("#[verifier::admit]"):
            logger.error("#[verifier::admit] annotations have been added or removed")
            return False

        with (
            tempfile.NamedTemporaryFile(mode="w", prefix="llm4v_orig", suffix=".rs", encoding="utf-8") as orig_f,
            tempfile.NamedTemporaryFile(mode="w", prefix="llm4v_changed", suffix=".rs", encoding="utf-8") as changed_f,
        ):
            orig_f.write(origin)
            orig_f.flush()
            changed_f.write(changed)
            changed_f.flush()

            m = self.run(["additions", orig_f.name, changed_f.name])

            if m.returncode == 0:
                return True
            elif m.returncode == 1:
                err_m = m.stdout.strip()
                # lynette safety check could output more information than just `Disallowed changes detected'
                if "Disallowed changes detected" in err_m:
                    logger.error("Disallowed changes detected by lynette")
                    return False
                else:
                    details = "\n".join(part for part in (m.stdout.strip(), m.stderr.strip()) if part)
                    if details.startswith("Checker error:"):
                        details = details[len("Checker error:"):].strip()
                    raise LynetteCheckerError(details or "Lynette rejected the check without a result")
            else:
                details = "\n".join(part for part in (m.stdout.strip(), m.stderr.strip()) if part)
                if details.startswith("Checker error:"):
                    details = details[len("Checker error:"):].strip()
                raise LynetteCheckerError(
                    details or f"Lynette exited with status {m.returncode}"
                )


def main():
    parser = argparse.ArgumentParser(description="Check if code changes are safe for proof completion.")
    parser.add_argument("origin_file", help="Path to the original source file")
    parser.add_argument("changed_file", help="Path to the modified source file")
    args = parser.parse_args()

    try:
        with open(args.origin_file, 'r', encoding='utf-8') as f:
            origin_content = f.read()
        with open(args.changed_file, 'r', encoding='utf-8') as f:
            changed_content = f.read()
    except FileNotFoundError as e:
        logger.error(f"Error reading files: {e}")
        sys.exit(1)

    lynette = Lynette()

    try:
        is_safe = lynette.proof_completion_code_change_is_safe(
            origin=origin_content,
            changed=changed_content
        )
    except LynetteCheckerError as e:
        print(f"Checker error: {e}", file=sys.stderr)
        sys.exit(2)

    if is_safe:
        print("Changes are safe.")
        sys.exit(0)
    else:
        print("Changes are NOT safe.")
        sys.exit(1)


if __name__ == "__main__":
    main()

